<script>
let dados=[],atual=null; const brl=v=>(Number(v)||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}); const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
async function api(url,opt){const r=await fetch(url,opt);const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Erro');return j}
async function carregar(){try{const j=await api('api.php?action=dashboard');dados=j.itens||[];kTotal.textContent=brl(j.resumo.totalAberto);kMat.textContent=j.resumo.matriculas;kAlunos.textContent=j.resumo.alunos;kPromessas.textContent=j.resumo.acordosAtivos??j.resumo.promessas;kNunca.textContent=j.resumo.nuncaContatados;relInfo.textContent=j.relatorio?`Relatório Sponte: ${j.relatorio.arquivo||'último importado'} • ${j.relatorio.importado_em||''}`:'Sem relatório Sponte: exibindo casos manuais/estimados.';render()}catch(e){relInfo.textContent=e.message}}
function badgeStatus(s){const map={pendente:['Pendente','orange'],em_cobranca:['Em cobrança','blue'],acordo:['Acordo','green'],regularizado:['Regularizado','green']};const x=map[s]||[s,'orange'];return `<span class="badge ${x[1]}">${x[0]}</span>`}
function render(){const q=busca.value.toLowerCase().trim(),st=status.value,ord=ordem.value;let a=dados.filter(x=>!x.ultimoContato&&(!q||`${x.aluno} ${x.turma} ${x.telefone||''}`.toLowerCase().includes(q))&&(!st||x.cobrancaStatus===st));a.sort((x,y)=>ord==='nome'?x.aluno.localeCompare(y.aluno):ord==='meses'?y.mesesInadimplencia-x.mesesInadimplencia:y.totalAberto-x.totalAberto);tbody.innerHTML=a.map(x=>`<tr><td><b>${esc(x.aluno)}</b><div class="muted">Matrícula interna #${x.matriculaId}</div></td><td>${esc(x.turma)}<div class="muted">${esc(x.dia)} • ${esc(x.horario)}</div></td><td>${esc(x.telefone||'—')}</td><td>${x.mesesInadimplencia||0}</td><td><b>${brl(x.totalAberto)}</b></td><td><span class="badge red">Inadimplente</span></td><td>${badgeStatus(x.cobrancaStatus)}</td><td>${esc(x.ultimoContato||'Nunca')}</td><td><div class="rowactions"><button class="btn light" onclick="abrir(${x.matriculaId},'contato')">Contatar</button></div></td></tr>`).join('')||'<tr><td colspan="9" style="text-align:center;padding:30px;color:#718096">Nenhum aluno aguardando primeiro contato neste filtro.</td></tr>'}
let relAtual=null;
function mostrar(v){document.querySelectorAll('.view').forEach(e=>e.classList.remove('active'));if(v==='dashboard'){document.getElementById('view-dashboard').classList.add('active');document.getElementById('fila').classList.add('active')}else{document.getElementById(v==='fila'?'fila':'view-'+v).classList.add('active')}document.querySelectorAll('.nav button[data-view]').forEach(e=>e.classList.toggle('active',e.dataset.view===v));if(['contatos','recebidos','acordos','regularizacoes'].includes(v))carregarListas();if(v==='relatorio')carregarRelatorio();window.scrollTo(0,0)}
function focarFila(){mostrar('fila')}
async function abrir(mid,modo="contato"){atual=dados.find(x=>x.matriculaId===mid);if(!atual)return;mAluno.textContent=atual.aluno;mTurma.textContent=atual.turma+' • '+atual.dia+' '+atual.horario;mTel.textContent=atual.telefone||'—';mValor.textContent=brl(atual.totalAberto);mMeses.textContent=atual.mesesInadimplencia||0;mStatus.innerHTML=badgeStatus(atual.cobrancaStatus);document.querySelectorAll('.modalgroup').forEach(e=>e.classList.remove('active'));document.getElementById('group-'+(modo==='regularizar'?'receber':modo)).classList.add('active');recTipo.value=modo==='regularizar'?'regularizacao_passada':'recebimento';recTitulo.textContent=modo==='regularizar'?'Registrar regularização passada':'Registrar recebimento';modal.classList.add('show');await historicoCarregar();await historicoFinanceiroCarregar()}
async function abrirPorId(mid,modo){if(!dados.some(x=>x.matriculaId===mid))await carregar();if(!dados.some(x=>x.matriculaId===mid)){alert('Matrícula não consta mais na fila financeira atual. Consulte o histórico.');return}await abrir(mid,modo)}
function fechar(){modal.classList.remove('show');atual=null}function togglePromessa(){promessaBox.style.display=resultado.value==='acordo_firmado'?'block':'none'}
async function historicoCarregar(){const j=await api('api.php?action=historico&matriculaId='+atual.matriculaId);historico.innerHTML=(j.historico||[]).map(h=>`<div class="histitem"><b>${esc(h.usuario_nome||'Sistema')}</b> • ${esc(h.canal)} • ${esc(h.resultado)}<div class="muted">${esc(h.criado_em)}</div><div>${esc(h.observacao||'')}</div>${h.promessa_data?`<div class="muted">Acordo: ${esc(h.promessa_data)} • ${brl(h.promessa_valor)}</div>`:''}</div>`).join('')||'<div class="muted">Nenhum contato registrado.</div>'}
async function salvarContato(){if(!atual)return;try{await api('api.php?action=registrar_contato',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({matriculaId:atual.matriculaId,canal:canal.value,resultado:resultado.value,observacao:obs.value,proximoContato:proximo.value,promessaData:promessaData.value,promessaValor:promessaValor.value})});obs.value='';proximo.value='';promessaData.value='';promessaValor.value='';await carregar();atual=dados.find(x=>x.matriculaId===atual.matriculaId);await historicoCarregar();await carregarListas();mStatus.innerHTML=badgeStatus(atual?.cobrancaStatus||'em_cobranca')}catch(e){alert(e.message)}}
// Chave PIX configurada localmente pela escola. Nunca inserir chave ficticia.
const CHAVE_PIX_LICEU = '10.651.278/0001-09'; // Chave PIX informada pela escola.
function mesReferencia(v){
  const t=String(v??'').trim();
  const m=t.match(/(?:^|\D)(0?[1-9]|1[0-2])[\/\-](20\d{2})(?:\D|$)/);
  if(m)return String(m[1]).padStart(2,'0')+'/'+m[2];
  const iso=t.match(/^(20\d{2})-(0[1-9]|1[0-2])(?:-\d{2})?$/);
  return iso?iso[2]+'/'+iso[1]:(t||'Não informado');
}
function dataBR(v){const t=String(v??'').trim();const m=t.match(/^(\d{4})-(\d{2})-(\d{2})/);return m?`${m[3]}/${m[2]}/${m[1]}`:(/^\d{2}\/\d{2}\/\d{4}$/.test(t)?t:'Não informado')}
function primeiraChave(o,keys){for(const k of keys){if(o?.[k]!==undefined&&o[k]!==null&&String(o[k]).trim()!=='')return o[k]}return null}
function parcelasEmAberto(item){
  const lista=Array.isArray(item.mesesAbertos)?item.mesesAbertos:[];
  return lista.map(x=>{
    if(typeof x==='string')return {mes:mesReferencia(x),valor:null,vencimento:null};
    if(!x||typeof x!=='object')return null;
    const mes=primeiraChave(x,['competencia','mes_ano','mesAno','referencia','mes','periodo','mensalidade']);
    const valor=primeiraChave(x,['valor_aberto','valorAberto','saldo_aberto','saldo','valor','total_aberto']);
    const vencimento=primeiraChave(x,['data_vencimento','dataVencimento','vencimento','dt_vencimento']);
    return {mes:mesReferencia(mes),valor:valor===null?null:Number(String(valor).replace(/R\$\s*/g,'').replace(/\./g,'').replace(',','.')),vencimento};
  }).filter(Boolean);
}
function abrirWhatsapp(){
  if(!atual)return;
  const tel=String(atual.responsavelTelefone||atual.telefone||'').replace(/\D/g,'');
  if(!tel){alert('Sem telefone cadastrado.');return}
  const pix=CHAVE_PIX_LICEU.trim();
  if(!pix){alert('Configure a chave PIX oficial em CHAVE_PIX_LICEU no arquivo cobranca/index.php antes de enviar cobranças.');return}
  const parcelas=parcelasEmAberto(atual);
  const total=Number(atual.totalAberto)||0;
  if(total<=0){alert('Não há valor em aberto confirmado para esta matrícula. Confira o cadastro antes de cobrar.');return}
  const responsavel=String(atual.responsavel||'').trim();
  const aluno=String(atual.aluno||'').trim();
  const saudacao=responsavel?`Prezado(a) ${responsavel}, esperamos que esteja bem!`:'Prezado(a) responsável, esperamos que esteja bem!';
  const linhas=[];
  if(parcelas.length){
    for(const p of parcelas){
      linhas.push(`📌 *Mensalidade:* ${p.mes}`);
      linhas.push(`💰 *Valor em aberto:* ${p.valor!==null&&Number.isFinite(p.valor)?brl(p.valor):'Conforme saldo total abaixo'}`);
      linhas.push(`📅 *Vencimento:* ${dataBR(p.vencimento)}`);
      linhas.push('');
    }
    linhas.push(`*Total em aberto:* ${brl(total)}`);
  }else{
    linhas.push('📌 *Mensalidade:* Não informada no relatório');
    linhas.push(`💰 *Valor em aberto:* ${brl(total)}`);
    linhas.push('📅 *Vencimento:* Não informado no relatório');
  }
  if(!confirm('Confira a competência, os valores e o vencimento na mensagem antes de enviar. A abertura do WhatsApp não confirma o envio. Continuar?'))return;
  const msg=[
    '*COMUNICADO FINANCEIRO | LICEU*',
    saudacao,
    ...(aluno?[`*Aluno(a):* ${aluno}`]:[]),
    'Identificamos em nosso sistema uma pendência referente à mensalidade abaixo:',
    ...linhas,
    'Solicitamos, por gentileza, a regularização do pagamento, conforme as condições contratuais, que poderá ser realizada de forma prática e segura via *PIX*.',
    `*Chave PIX:* ${pix}`,
    'Caso o pagamento já tenha sido efetuado, pedimos que desconsidere este aviso.',
    'Atenciosamente,',
    '*Setor Financeiro | Liceu*'
  ].join('\n');
  window.open('https://wa.me/55'+tel.replace(/^55/,'')+'?text='+encodeURIComponent(msg),'_blank','noopener');
}
const hojeLocal=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
recData.value=hojeLocal();relDia.value=hojeLocal();
async function salvarRecebimento(){if(!atual)return;const mid=atual.matriculaId;try{const j=await api('api.php?action=registrar_recebimento',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({matriculaId:mid,valor:recValor.value,data:recData.value,tipo:recTipo.value,origem:recOrigem.value,observacao:recObs.value})});recValor.value='';recObs.value='';await historicoFinanceiroCarregar();await carregarListas();alert(j.aviso||'Recebimento registrado.')}catch(e){alert(e.message)}}
async function salvarAcordo(){if(!atual)return;const mid=atual.matriculaId;try{await api('api.php?action=registrar_acordo',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({matriculaId:mid,valor:acValor.value,vencimento:acData.value,observacao:acObs.value})});acValor.value='';acObs.value='';await historicoFinanceiroCarregar();await carregar();await carregarListas();alert('Acordo programado.')}catch(e){alert(e.message)}}
async function historicoFinanceiroCarregar(){if(!atual)return;try{const j=await api('api.php?action=historico_financeiro&matriculaId='+atual.matriculaId);historicoFinanceiro.innerHTML='<div class="sectiontitle">Histórico financeiro da cobrança</div>'+(j.recebimentos||[]).map(r=>`<div class="histitem"><b>${esc(r.data_recebimento)} • ${brl(r.valor)}</b> — ${esc(r.tipo)} / ${esc(r.origem)}<div class="mini">${esc(r.usuario_nome)} • ${esc(r.criado_em)}</div><div>${esc(r.observacao||'')}</div></div>`).join('')+(j.acordos||[]).map(r=>`<div class="histitem"><b>Acordo ${esc(r.vencimento)} • ${brl(r.valor_previsto)}</b> — ${esc(r.status)}<div>${esc(r.observacao||'')}</div></div>`).join('')||'<div class="mini">Sem registros financeiros.</div>'}catch(e){historicoFinanceiro.textContent=e.message}}
let listasGestao={contatos:[],recebidos:[],acordos:[],regularizacoes:[]};
const opcoesGestao={contatos:[['','Todos os status'],['sem_resposta','Sem retorno'],['retornar','Retornar'],['em_negociacao','Em negociação'],['contato_realizado','Contato realizado'],['acordo_firmado','Acordo firmado'],['regularizado','Regularizado']],recebidos:[['','Todas as origens'],['informado_aluno','Informado pelo aluno'],['comprovante','Comprovante'],['confirmado_financeiro','Confirmado pelo financeiro']],acordos:[['','Todos os status'],['Dentro do prazo','Dentro do prazo'],['Vence hoje','Vence hoje'],['Vencido','Vencidos'],['cumprido','Cumpridos'],['cancelado','Cancelados'],['regularizado','Regularizados']],regularizacoes:[['','Todos os tipos'],['regularizacao_passada','Regularização passada']]};
function inicializarFiltrosGestao(){for(const [sec,opts] of Object.entries(opcoesGestao)){const el=document.getElementById('f-'+sec+'-status');if(el&&!el.options.length)el.innerHTML=opts.map(([v,l])=>`<option value="${esc(v)}">${esc(l)}</option>`).join('')}}
function limparFiltrosGestao(sec){for(const sufixo of ['busca','inicio','fim','status']){const el=document.getElementById('f-'+sec+'-'+sufixo);if(el)el.value=''}filtrarGestao(sec)}
function selecionarStatusContato(st){const el=document.getElementById('f-contatos-status');el.value=st==='todos'?'':st;filtrarGestao('contatos')}
function filtrarGestao(sec){const rows=listasGestao[sec]||[];const val=(sufixo)=>document.getElementById('f-'+sec+'-'+sufixo)?.value||'';const busca=val('busca').trim().toLocaleLowerCase('pt-BR'),inicio=val('inicio'),fim=val('fim'),status=val('status');const campoData={contatos:'criado_em',recebidos:'data_recebimento',acordos:'vencimento',regularizacoes:'data_recebimento'}[sec];const filtrados=rows.filter(x=>{const data=String(x[campoData]||'').slice(0,10);if(inicio&&(!data||data<inicio))return false;if(fim&&(!data||data>fim))return false;const situacao=sec==='contatos'?x.resultado:sec==='acordos'?(x.statusEfetivo||x.status):sec==='recebidos'?x.origem:x.tipo;if(status&&!(sec==='contatos'&&status==='em_negociacao'&&situacao==='acordo_firmado')&&situacao!==status)return false;return !busca||[x.aluno,x.turma,x.usuario_nome,x.observacao,x.canal,x.resultado,x.origem,x.statusEfetivo,x.valor_previsto,x.valor].some(v=>String(v??'').toLocaleLowerCase('pt-BR').includes(busca))});const vazio=(n)=>`<tr><td colspan="${n}" class="muted" style="padding:20px">Nenhum registro para os filtros selecionados.</td></tr>`;
if(sec==='contatos')tabContatos.innerHTML=filtrados.map(x=>`<tr><td>${esc(x.criado_em)}</td><td>${esc(x.aluno)}</td><td>${esc(x.turma)}</td><td>${esc(x.canal)}</td><td>${esc(x.resultado)}</td><td>${esc(x.usuario_nome)}</td><td>${esc(x.observacao)}</td><td><div class="rowactions"><button class="btn light" onclick="abrirPorId(${Number(x.matricula_id)},'contato')">Contatar</button><button class="btn primary" onclick="abrirPorId(${Number(x.matricula_id)},'receber')">Receber</button><button class="btn light" onclick="abrirPorId(${Number(x.matricula_id)},'regularizar')">Regularizar</button></div></td></tr>`).join('')||vazio(8);
if(sec==='recebidos')tabRecebidos.innerHTML=filtrados.map(x=>`<tr><td>${esc(x.data_recebimento)}</td><td>${esc(x.aluno)}</td><td>${esc(x.turma)}</td><td>${brl(x.valor)}</td><td>${esc(x.origem)}</td><td>${esc(x.usuario_nome)}</td><td>${esc(x.observacao)}</td></tr>`).join('')||vazio(7);
if(sec==='acordos')tabAcordos.innerHTML=filtrados.map(x=>`<tr><td>${esc(x.vencimento)}</td><td>${esc(x.aluno)}</td><td>${esc(x.turma)}</td><td>${brl(x.valor_previsto)}</td><td>${esc(x.statusEfetivo||x.status)}</td><td>${esc(x.usuario_nome)}</td><td>${esc(x.observacao)}</td><td><div class="rowactions"><button class="btn light" onclick="abrirPorId(${Number(x.matricula_id)},'contato')">Cobrar</button><button class="btn primary" onclick="abrirPorId(${Number(x.matricula_id)},'receber')">Receber</button><button class="btn light" onclick="abrirPorId(${Number(x.matricula_id)},'regularizar')">Regularizar</button></div></td></tr>`).join('')||vazio(8);
if(sec==='regularizacoes')tabRegularizacoes.innerHTML=filtrados.map(x=>`<tr><td>${esc(x.data_recebimento)}</td><td>${esc(x.aluno)}</td><td>${esc(x.turma)}</td><td>${brl(x.valor)}</td><td>${esc(x.observacao)}</td><td>${esc(x.usuario_nome)}</td></tr>`).join('')||vazio(6);
}
async function carregarListas(){try{const j=await api('api.php?action=listas_gestao');for(const sec of Object.keys(listasGestao))listasGestao[sec]=j[sec]||[];inicializarFiltrosGestao();const aResumo=j.resumoAcordos||{};for(const [id,chave,formato] of [['acValorAberto','aberto',true],['acValorPrazo','prazo',true],['acValorVencido','vencidos',true],['acValorEncerrado','encerrados',true],['acQtdAberto','aberto',false],['acQtdPrazo','prazo',false],['acQtdVencido','vencidos',false],['acQtdEncerrado','encerrados',false]]){const el=document.getElementById(id);if(el)el.textContent=formato?brl(aResumo[chave]?.valor??0):`${aResumo[chave]?.quantidade??0} acordos`;}const ultimos=new Map();for(const x of listasGestao.contatos){const key=String(x.matricula_id);if(!ultimos.has(key))ultimos.set(key,x)}const c=Array.from(ultimos.values());ctTotal.textContent=c.length;ctSemRetorno.textContent=c.filter(x=>x.resultado==='sem_resposta').length;ctRetornar.textContent=c.filter(x=>x.resultado==='retornar').length;ctNegociacao.textContent=c.filter(x=>x.resultado==='em_negociacao'||x.resultado==='acordo_firmado').length;for(const sec of Object.keys(listasGestao))filtrarGestao(sec)}catch(e){alert(e.message)}}
async function carregarRelatorio(){try{const j=await api('api.php?action=relatorio_diario&dia='+encodeURIComponent(relDia.value));relAtual=j;relTitulo.textContent='Dia '+relDia.value.split('-').reverse().join('/');rContatos.textContent=j.resumo.contatos;rQtd.textContent=j.resumo.recebimentos;rAcordos.textContent=j.resumo.acordos;rValor.textContent=brl(j.resumo.valorInformado);relResumo.textContent=`Desse total, confirmado pelo Financeiro: ${brl(j.resumo.valorConfirmado)} | Regularizações passadas: ${j.resumo.regularizacoes} (fora do total recebido). Os valores informados pela equipe não são confirmação de crédito bancário.`;relRecebimentos.innerHTML=(j.recebimentos||[]).map(x=>`<tr><td>${esc(x.aluno)}</td><td>${esc(x.turma)}</td><td>${brl(x.valor)}</td><td>${esc(x.origem)}</td><td>${esc(x.usuario_nome)}</td></tr>`).join('')||'<tr><td colspan="5">Nenhum recebimento.</td></tr>';relContatos.innerHTML=(j.contatos||[]).map(x=>`<tr><td>${esc(x.criado_em)}</td><td>${esc(x.aluno)}</td><td>${esc(x.canal)}</td><td>${esc(x.resultado)}</td><td>${esc(x.usuario_nome)}</td></tr>`).join('')||'<tr><td colspan="5">Nenhum contato.</td></tr>'}catch(e){relResumo.textContent=e.message}}
function compartilharRelatorio(){if(!relAtual){alert('Consulte o relatório primeiro.');return}const r=relAtual.resumo;const txt=`*Liceu Brasil — Relatório de Cobranças*\n*Data:* ${relDia.value.split('-').reverse().join('/')}\n\nContatos realizados: ${r.contatos}\nRecebimentos: ${r.recebimentos}\nAcordos programados: ${r.acordos}\nValor recebido registrado: ${brl(r.valorInformado)}\nConfirmado pelo Financeiro: ${brl(r.valorConfirmado)}\nRegularizações anteriores: ${r.regularizacoes}\n\n_Valores informados pela equipe; não representam necessariamente crédito bancário confirmado._`;window.open('https://wa.me/?text='+encodeURIComponent(txt),'_blank','noopener')}
modal.addEventListener('click',e=>{if(e.target===modal)fechar()});carregar();
